'use strict';
// AI Policy Assistant — grounded answer layer (no DOM).
// The language model only chooses WHICH supported analysis a question asks for. Every number below is produced by
// the Studio's validated functions in analysis.js (window.PDS), applied to the packaged country files — the same
// functions and default settings the main analysis pages use. Nothing here is generated by the model.
(function (root) {
  const P = root.PDS || (typeof require !== 'undefined' ? require('./analysis.js') : null);
  if (!P) throw Error('analysis.js (PDS) must be loaded before ai_policy_core.js');

  // Example phrasings used for on-device semantic matching (embeddings) — one list per supported analysis.
  const TOPICS = [
    {id: 'poverty', label: 'Regional poverty and inequality', examples: ['Where is poverty highest in the country?', 'Which regions have the most people living in poverty?', 'Compare poverty rates across districts and counties.', 'How unequal are regions in terms of poverty?']},
    {id: 'spending', label: 'Observed public spending versus need', examples: ['Does state government spending match where poor people live?', 'Compare public expenditure per resident across states.', 'Do poorer regions receive more government spending per person?', 'How is public money actually spent across regions?']},
    {id: 'allocation', label: 'Hypothetical funding rules', examples: ['How would a budget be divided between districts under a funding formula?', 'Compare allocating money per resident versus per poor person.', 'Which areas would gain if funds were allocated by number of poor people?', 'Simulate a needs-based allocation rule for a fixed budget.']},
    {id: 'human', label: 'Health, education and human development', examples: ['Where are child health outcomes worse?', 'Which regions have the highest stunting?', 'Compare vaccination coverage across regions.', 'Where are education and literacy lowest?']},
    {id: 'climate', label: 'Climate exposure', examples: ['Which regions had unusual rainfall recently?', 'Where was it drier than normal?', 'Which areas face drought or rainfall anomalies?', 'Compare rainfall across regions.']},
  ];
  const KEYWORDS = {
    poverty: ['poverty', 'poor', 'inequality', 'gini', 'deprivation', 'headcount', 'welfare', 'consumption'],
    spending: ['spending', 'spend', 'expenditure', 'fiscal', 'public money', 'per resident', 'state government', 'outlays'],
    allocation: ['allocat', 'formula', 'divide', 'divided', 'funding rule', 'per poor person', 'distribute', 'budget of', 'hypothetical', 'simulate'],
    human: ['health', 'stunt', 'vaccin', 'immunis', 'immuniz', 'education', 'literacy', 'school', 'nutrition', 'anaemia', 'anemia', 'hiv', 'mortality', 'child', 'fertility', 'water', 'sanitation', 'electricity', 'contracept'],
    climate: ['rain', 'drought', 'climate', 'precipitation', 'wetter', 'drier', 'dry', 'flood'],
  };
  // Questions the Studio cannot answer from its data. Checked before any routing, in both modes.
  const OUT_OF_SCOPE = [
    [/\b(forecast|predict|projection|projected|next (year|decade)|by 20[3-9]\d|in 20[3-9]\d|future)\b|\bwill\b.*\b(be|grow|reach|rise|fall)\b/i, 'forecast',
      'The Studio does not make forecasts or projections. It reports published estimates for past survey years.'],
    [/\b(will|would|does|do|did|can)\b.*\b(reduce|lower|increase|raise|improve|affect|impact|cause|lead to|lift)\b|\b(impact|effect|caus(e|al)|effective(ness)?)\b/i, 'causal',
      'The Studio does not estimate the effects of policies or programmes. It shows descriptive data and hypothetical allocation formulas, not causal evidence.'],
    [/\b(should|ought|best|optimal|optimi[sz]e|recommend|ideal|right amount)\b/i, 'normative',
      'The Studio does not recommend policies or define an optimal allocation. It can show how different funding rules would divide a budget.'],
    [/\b(gdp|inflation|interest rate|exchange rate|unemployment|election|president|capital city|joke|weather (today|tomorrow)|stock|crypto|recipe)\b/i, 'off-topic',
      'This question is outside the Studio’s four analysis areas (regional poverty, public spending and need, health and human development, climate exposure).'],
  ];
  const LEVEL = P.LEVEL, LINES = P.LINES;
  const WELFARE = {CONS: 'consumption', INC: 'income'};
  const F = (x, d = 1) => x == null || !isFinite(x) ? 'n/a' : Number(x).toLocaleString('en-GB', {maximumFractionDigits: d, minimumFractionDigits: d});
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
  const defaultLine = info => /upper middle|high/i.test(info?.income || '') ? 'poor830' : /lower middle/i.test(info?.income || '') ? 'poor420' : 'poverty_rate';
  const PIP_ID = line => 'wb_pip:headcount_' + {poverty_rate: '300', poor420: '420', poor830: '830'}[line];
  const SRC = {
    spid: 'World Bank Subnational Poverty and Inequality Database (SPID), CC BY 4.0',
    pip: 'World Bank Poverty and Inequality Platform (PIP), CC BY 4.0',
    worldpop: 'WorldPop 1 km gridded population (modelled), CC BY 4.0',
    siconfi: 'Brazil National Treasury SICONFI state accounts (executed expenditure, nominal BRL)',
    ibge: 'IBGE state population estimates published with SICONFI',
    dhs: 'The DHS Program (ICF) published regional estimates',
    chirps: 'CHIRPS v2.0 rainfall (Climate Hazards Center, UC Santa Barbara); public domain',
  };

  function outOfScope(q) {
    for (const [rx, kind, msg] of OUT_OF_SCOPE) if (rx.test(q)) return {kind, message: msg};
    return null;
  }
  function keywordTopic(q) {
    const s = q.toLowerCase();
    const score = Object.fromEntries(Object.entries(KEYWORDS).map(([k, ws]) => [k, ws.reduce((n, w) => n + (s.includes(w) ? 1 : 0), 0)]));
    if (score.allocation > 0) score.allocation += 0.5;   // "budget divided per poor person" is allocation, not observed spending
    const best = Object.keys(score).sort((a, b) => score[b] - score[a])[0];
    return score[best] > 0 ? {topic: best, score: score[best]} : null;
  }
  // Country named in the question (name or common adjective form), longest names first.
  function detectCountry(q, countries) {
    const s = ' ' + q.toLowerCase().replace(/[^a-zÀ-ɏ ]/g, ' ') + ' ';
    const list = countries.slice().sort((a, b) => b.name.length - a.name.length);
    for (const c of list) {
      const n = c.name.toLowerCase().replace(/[^a-zÀ-ɏ ]/g, ' ').replace(/\s+/g, ' ').trim();
      if (n.length < 4) continue;
      const stem = n.replace(/[aey]$/, '');
      const rx = new RegExp(`\\s(${n}|${stem}(n|an|ian|ese|i))\\s`);
      if (rx.test(s)) return c;
    }
    return null;
  }
  function pipOfficial(doc, line, year, welfare) {
    const s = doc.national.find(x => x.i === PIP_ID(line) && x.b === `area=national;welfare=${WELFARE[welfare] || welfare}`);
    const p = s?.d.find(x => x[0] === year);
    return p ? p[1] * 100 : null;
  }
  function validation(official, wrate, year) {
    if (official == null) return `No official national estimate for ${year} with the same welfare measure to compare against.`;
    if (wrate == null) return `Official national figure for ${year}: ${F(official)}% (regional values cannot be re-weighted without population estimates).`;
    return `Population-weighted regional estimates give ${F(wrate)}%; the official national figure for ${year} (same line and welfare measure) is ${F(official)}% — a difference of ${F(Math.abs(wrate - official))} percentage points.`;
  }
  function matchD1(doc, set) {
    return P.runnable(doc, 'D1').find(x => x.year === set.year && x.survey === set.survey && x.n_units === set.n && set.period.u.every(u => x.rows.some(r => r.geo_code === u[0])));
  }
  const base = (doc, info, intent, extra) => ({intent, country: info.name, iso3: doc.iso3, label: TOPICS.find(t => t.id === intent)?.label, ...extra});
  const unavailable = (doc, info, intent, why, href) => base(doc, info, intent, {status: 'unavailable', kind: 'Not available', heading: `${info.name}: ${TOPICS.find(t => t.id === intent).label}`, facts: [], message: why, assumptions: [], limitations: [], href, computedWith: []});

  function poverty(doc, info, line, wantsCount) {
    const sets = P.povertySets(doc).slice().reverse();
    if (!sets.length) return unavailable(doc, info, 'poverty', `No verified regional poverty estimates exist for ${info.name}; only national figures (if any) are available.`, `#/c/${doc.iso3}/poverty`);
    const set = sets[0], d1 = matchD1(doc, set), L = LINES[line];
    const codes = new Set(set.period.u.map(u => u[0]));
    const rate = P.valuesFor(doc, L.spid, set.year, codes, set.survey);
    const pop = d1 ? new Map(d1.rows.map(r => [r.geo_code, r.population])) : new Map();
    const rows = set.period.u.map(u => ({name: u[1], rate: rate.get(u[0])?.v != null ? rate.get(u[0]).v * 100 : null, population: pop.get(u[0]) ?? null}));
    const rs = P.rankSummary(rows, 'rate');
    const withPop = rows.filter(r => r.rate != null && r.population != null);
    const wrate = d1 ? P.weightedRate(withPop.map(r => ({population: r.population, poverty_rate: r.rate}))) : null;
    const conc = d1 ? P.concentration(withPop.map(r => ({population: r.population, poverty_rate: r.rate, name: r.name}))) : null;
    const largest = conc ? conc.top[0] : null;
    const official = pipOfficial(doc, line, set.year, set.welfare);
    const facts = [
      {text: `Survey: ${set.survey} ${set.year}, ${set.n} ${LEVEL[set.level] || set.level}; poverty line ${L.label} per person (2021 purchasing-power prices), ${WELFARE[set.welfare] || set.welfare}-based.`, source: SRC.spid},
      rs && {text: `The share of people below the line ranges from ${F(rs.lowest.rate)}% in ${rs.lowest.name} to ${F(rs.highest.rate)}% in ${rs.highest.name}.`, source: SRC.spid},
      largest && {text: `${largest.name} has the largest number of people below the line (about ${F(largest.poor, 0)}); ${F(conc.topShare * 100, 0)}% of the ${F(conc.poor / 1e6, 2)} million people below the line live in the ${conc.top.length} areas with most poor people.`, source: `${SRC.spid}; ${SRC.worldpop}`},
      official != null && {text: `Official national rate for ${set.year}: ${F(official)}%.`, source: SRC.pip},
    ].filter(Boolean);
    if (wantsCount && largest) facts.unshift(facts.splice(facts.findIndex(f => f.text.includes('largest number')), 1)[0]);
    return base(doc, info, 'poverty', {status: 'ok', kind: 'Descriptive evidence', heading: `${info.name}: regional poverty (${set.survey} ${set.year})`, facts,
      validation: validation(official, wrate, set.year),
      uncertainty: 'No standard errors are published for these regional estimates; differences of a few points may not be statistically meaningful.' + (d1 ? ' Population counts are modelled (WorldPop).' : ''),
      assumptions: [`Poverty line: ${L.label}, the default for ${info.income || 'this income group'} (change it in the full analysis).`, d1 ? 'People in poverty = area population × poverty share.' : 'No population estimate for this survey year, so numbers of poor people are not computed.'],
      limitations: ['Descriptive: shows where poverty is high, not why.', 'Not comparable with other survey rounds unless survey and welfare measure match.'],
      href: `#/c/${doc.iso3}/poverty?set=0&line=${line}&m=${wantsCount && d1 ? 'poor' : 'rate'}`,
      computedWith: ['PDS.povertySets', 'PDS.valuesFor', 'PDS.rankSummary', d1 && 'PDS.weightedRate', d1 && 'PDS.concentration'].filter(Boolean)});
  }

  function allocation(doc, info, line) {
    const sets = P.runnable(doc, 'D1').slice().sort((a, b) => b.year - a.year || b.n_units - a.n_units);
    if (!sets.length) return unavailable(doc, info, 'allocation', `Hypothetical funding rules need regional poverty and population for the same areas and year; these are not available for ${info.name}.`, `#/c/${doc.iso3}/spending`);
    const set = sets[0], L = LINES[line];
    const rows = set.rows.map(r => ({name: r.name, population: r.population, poverty_rate: r[line]}));
    const pop = P.allocation(rows, 100e6, 'population', 0), poor = P.allocation(rows, 100e6, 'poor', 0);
    const top = poor.rows.slice().sort((a, b) => b.share - a.share)[0];
    const gains = poor.rows.map((r, i) => ({name: r.name, d: r.share - pop.rows[i].share, from: pop.rows[i].share, to: r.share})).sort((a, b) => b.d - a.d);
    const moved = gains.filter(g => g.d > 0).reduce((s, g) => s + g.d, 0);
    const wrate = P.weightedRate(rows), official = pipOfficial(doc, line, set.year, P.povertySets(doc).find(s => s.year === set.year && s.survey === set.survey)?.welfare);
    const hasObserved = P.runnable(doc, 'D2').length > 0, last = gains[gains.length - 1];
    return base(doc, info, 'allocation', {status: 'ok', kind: 'Hypothetical allocation', heading: `${info.name}: hypothetical funding rules (${set.survey} ${set.year}, ${set.n_units} areas)`,
      facts: [
        {text: `Under a “same amount per poor person” rule (people below ${L.label}), ${top.name} would receive the largest share: ${F(top.share * 100)}% of the budget.`, source: `${SRC.spid}; population as documented in the analysis`},
        {text: `Moving from “same amount per resident” to “same amount per poor person” shifts ${F(moved * 100, 0)}% of the budget between areas; ${gains[0].name} gains most (${F(gains[0].from * 100)}% → ${F(gains[0].to * 100)}%), ${last.name} loses most (${F(last.from * 100)}% → ${F(last.to * 100)}%).`, source: 'Studio allocation formula (PDS.allocation), tested against the original v0.1 formula'},
        {text: 'Shares sum to 100% under every rule; the budget amount (illustrative) only rescales the amounts.', source: 'PDS.allocation'},
      ],
      validation: 'Need input: ' + validation(official, wrate, set.year) + ' The allocations are a formula illustration and cannot be validated against outcomes.',
      uncertainty: 'Allocations inherit the unpublished sampling error of the poverty estimates and the modelling error of population estimates; no uncertainty range is computed.',
      assumptions: ['Illustrative budget of 100 million in any currency.', `Need measured as people below ${L.label} (default for this income group).`],
      limitations: ['Not a prediction of poverty reduction, programme effectiveness or optimal government spending.', hasObserved ? 'Observed spending is a separate analysis (“Observed spending vs need”).' : `Observed regional spending is not available for ${info.name}; this is not actual spending.`],
      href: `#/c/${doc.iso3}/spending?mode=rules&set=0&line=${line}&budget=100&rule=poor`,
      computedWith: ['PDS.runnable', 'PDS.allocation', 'PDS.weightedRate']});
  }

  function spending(doc, info, line) {
    const d2 = P.runnable(doc, 'D2').slice().sort((a, b) => b.year - a.year);
    if (!d2.length) {
      const alt = allocation(doc, info, line);
      return {...unavailable(doc, info, 'spending', `Observed regional spending is not available for ${info.name}: no verified dataset attributes government spending to its regions, so actual spending cannot be compared with need.${alt.status === 'ok' ? ' The hypothetical funding-rule analysis is shown instead — it is not actual spending.' : ''}`, `#/c/${doc.iso3}/spending`), fallback: alt.status === 'ok' ? alt : null};
    }
    const set = d2[0], L = LINES[line];
    const rows = P.spendingAlignment(set.rows.map(r => ({name: r.name, population: r.population, poverty_rate: r[line], spending: r.spending})));
    const avg = rows.reduce((s, r) => s + r.spending, 0) / rows.reduce((s, r) => s + r.population, 0);
    const top5 = rows.slice().sort((a, b) => b.poverty_rate - a.poverty_rate).slice(0, 5);
    const t5pop = top5.reduce((s, r) => s + r.population, 0), t5sp = top5.reduce((s, r) => s + r.spending, 0);
    const sp = P.rankSummary(rows, 'spendPer');
    const official = pipOfficial(doc, line, set.year, 'INC'), wrate = P.weightedRate(rows);
    return base(doc, info, 'spending', {status: 'ok', kind: 'Observed expenditure comparison', heading: `${info.name}: state-government spending and poverty (${set.year})`,
      facts: [
        {text: `Average state-government spending was R$ ${F(avg, 0)} per resident in ${set.year} (all functions, ${rows.length} states).`, source: `${SRC.siconfi}; ${SRC.ibge}`},
        {text: `The 5 states with the highest poverty rates (below ${L.label}) spent R$ ${F(t5sp / t5pop, 0)} per resident; they hold ${F(top5.reduce((s, r) => s + r.poorShare, 0) * 100, 0)}% of poor people and ${F(top5.reduce((s, r) => s + r.spendShare, 0) * 100, 0)}% of this spending.`, source: `${SRC.siconfi}; ${SRC.spid}`},
        {text: `Spending per resident ranges from R$ ${F(sp.lowest.spendPer, 0)} (${sp.lowest.name}) to R$ ${F(sp.highest.spendPer, 0)} (${sp.highest.name}), a ${F(sp.ratio)}× difference.`, source: SRC.siconfi},
      ],
      validation: 'Poverty input: ' + validation(official, wrate, set.year) + ' State spending totals reconcile with the function lines in the Treasury accounts (automated test).',
      uncertainty: 'Spending is administrative (no sampling error, but reporting and classification differences); poverty estimates carry unpublished sampling error.',
      assumptions: [`Poverty line ${L.label} (default for ${info.income || 'this income group'}); population: official IBGE estimates.`, 'All state spending; health, education and social assistance can be selected in the full analysis.'],
      limitations: ['State-government accounts only: federal and municipal spending are excluded.', 'Not benefit incidence — spending recorded in a state is not the same as benefits received by poor households.', 'Nominal reais: compare states within a year only.'],
      href: `#/c/${doc.iso3}/spending?mode=observed&year=${set.year}&cat=total&line=${line}`,
      computedWith: ['PDS.runnable', 'PDS.spendingAlignment', 'PDS.rankSummary', 'PDS.weightedRate']});
  }

  const HUMAN_MAP = [[/stunt/i, 'dhs_api:CN_NUTS_C_HA2'], [/wast/i, 'dhs_api:CN_NUTS_C_WH2'], [/underweight/i, 'dhs_api:CN_NUTS_C_WA2'], [/vaccin|immuni/i, 'dhs_api:CH_VACC_C_BAS'],
    [/an(a)?emi/i, 'dhs_api:AN_ANEM_W_ANY'], [/hiv/i, 'dhs_api:HA_HIVP_B_HIV'], [/literac/i, 'dhs_api:ED_LITR_W_LIT'], [/secondary|education/i, 'dhs_api:ED_EDAT_W_SEC'],
    [/contracept|family planning/i, 'dhs_api:FP_CUSM_W_MOD'], [/fertility/i, 'dhs_api:FE_FRTR_W_TFR'], [/electric/i, 'dhs_api:HC_ELEC_H_ELC'], [/water/i, 'dhs_api:WS_SRCE_P_BAS'],
    [/sanitation|toilet/i, 'dhs_api:WS_TLET_P_BAS'], [/bed ?net|malaria/i, 'dhs_api:ML_NETC_C_ITN']];
  function human(doc, info, q, catalog) {
    const ids = Object.keys(doc.subnational).filter(k => k.startsWith('dhs_api:'));
    if (!ids.length) return unavailable(doc, info, 'human', `No regional health or demographic survey estimates are available for ${info.name}.`, `#/c/${doc.iso3}/human?view=nat`);
    const hit = HUMAN_MAP.find(([rx, id]) => rx.test(q) && ids.includes(id));
    const ind = hit ? hit[1] : (ids.includes('dhs_api:CN_NUTS_C_HA2') ? 'dhs_api:CN_NUTS_C_HA2' : ids[0]);
    const pers = P.periods(doc, ind), latestY = Math.max(...pers.map(p => p.y));
    const pi = pers.reduce((b, p, i) => p.y === latestY && (b < 0 || p.u.length > pers[b].u.length) ? i : b, -1), p = pers[pi];
    const items = p.u.map(u => ({label: String(u[1]).replace(/^\.+/, ''), value: u[2], lo: u[3]}));
    const rs = P.rankSummary(items, 'value'), title = catalog?.get(ind)?.t || ind, ci = items.filter(i => i.lo != null).length;
    return base(doc, info, 'human', {status: 'ok', kind: 'Descriptive evidence', heading: `${info.name}: ${title} (${p.y})`,
      facts: [
        {text: `${title}: highest in ${rs.highest.label} (${F(rs.highest.value)}), lowest in ${rs.lowest.label} (${F(rs.lowest.value)}), across ${items.length} ${LEVEL[p.lv] || 'areas'} (${p.b.replace('survey=', '')} survey).`, source: SRC.dhs},
        !hit && {text: `Your question did not name a specific indicator, so the Studio shows ${title}. Other available indicators: ${ids.filter(i => i !== ind).slice(0, 6).map(i => catalog?.get(i)?.t || i).join('; ')}.`, source: SRC.dhs},
      ].filter(Boolean),
      validation: 'Shown exactly as published by The DHS Program; not re-estimated by the Studio.',
      uncertainty: ci ? `95% confidence intervals are published for ${ci} of ${items.length} areas; overlapping intervals mean differences may not be meaningful.` : 'No confidence intervals are published for this indicator and survey; small differences may not be meaningful.',
      assumptions: ['Latest survey with the most detailed geography.'], limitations: ['Survey regions are defined separately in each survey; no regional trends are implied.', 'Descriptive only: does not explain differences.'],
      href: `#/c/${doc.iso3}/human?view=dhs&ind=${encodeURIComponent(ind)}&p=${pi}`, computedWith: ['PDS.periods', 'PDS.rankSummary']});
  }

  function climate(doc, info, line) {
    const sets = P.povertySets(doc).slice().reverse(), ch = P.periods(doc, 'chirps:precip_anomaly_pct');
    if (!sets.length || !ch.length) return unavailable(doc, info, 'climate', `Regional rainfall summaries are not available for ${info.name} (they exist only for areas on the regional poverty map between 50°S and 50°N).`, `#/c/${doc.iso3}/climate`);
    const set = sets[0], codes = new Set(set.period.u.map(u => u[0])), year = Math.max(...ch.map(p => p.y));
    const an = P.valuesFor(doc, 'chirps:precip_anomaly_pct', year, codes), L = LINES[line];
    const pov = P.valuesFor(doc, L.spid, set.year, codes, set.survey);
    const rows = set.period.u.map(u => ({name: u[1], anom: an.get(u[0])?.v ?? null, pov: pov.get(u[0])?.v != null ? pov.get(u[0]).v * 100 : null})).filter(r => r.anom != null).sort((a, b) => a.anom - b.anom);
    if (!rows.length) return unavailable(doc, info, 'climate', `No rainfall values for ${info.name}'s areas in ${year}.`, `#/c/${doc.iso3}/climate`);
    const dry = rows.filter(r => r.anom <= -15), wet = rows[rows.length - 1];
    return base(doc, info, 'climate', {status: 'ok', kind: 'Descriptive context', heading: `${info.name}: rainfall in ${year} compared with normal`,
      facts: [
        {text: `Driest relative to its 1991–2020 average: ${rows[0].name} (${F(rows[0].anom, 0)}%); wettest: ${wet.name} (${wet.anom > 0 ? '+' : ''}${F(wet.anom, 0)}%).`, source: SRC.chirps},
        {text: dry.length ? `${dry.length} areas were at least 15% drier than normal; ${dry.filter(r => r.pov != null && r.pov >= 50).length} of them have poverty rates of 50% or more (${set.survey} ${set.year}, ${L.label}).` : `No area was 15% or more drier than normal in ${year}.`, source: `${SRC.chirps}; ${SRC.spid}`},
      ],
      validation: 'Area averages are computed by the Studio from CHIRPS grids; not compared with national meteorological records.',
      uncertainty: 'CHIRPS publishes no uncertainty for annual totals; small anomalies may be within estimation error.',
      assumptions: [`Areas: poverty-map boundaries for ${set.survey} ${set.year}; rainfall year ${year}.`], limitations: ['Context only: no effect of rainfall on poverty or incomes is estimated.', 'Rainfall and poverty refer to different years.'],
      href: `#/c/${doc.iso3}/climate`, computedWith: ['PDS.povertySets', 'PDS.periods', 'PDS.valuesFor']});
  }

  // Main entry: intent → grounded answer using validated functions only.
  function answer(doc, info, intent, opts = {}) {
    const line = opts.line || defaultLine(info), q = opts.question || '';
    if (intent === 'poverty') return poverty(doc, info, line, /\b(number|how many|most (poor )?people|largest)\b/i.test(q));
    if (intent === 'spending') return spending(doc, info, line);
    if (intent === 'allocation') return allocation(doc, info, line);
    if (intent === 'human') return human(doc, info, q, opts.catalog);
    if (intent === 'climate') return climate(doc, info, line);
    throw Error('Unsupported intent: ' + intent);
  }

  const api = {TOPICS, KEYWORDS, outOfScope, keywordTopic, detectCountry, answer, defaultLine, esc};
  root.PDSAICore = api;
  if (typeof module !== 'undefined') module.exports = api;
})(typeof window !== 'undefined' ? window : globalThis);
